//! S03 contract battery: the reader projection over the pinned mixed WordML
//! fixture, read through the frozen `source_package` substrate and checked
//! against the independent `reader_verifier`.
//!
//! The per-view fragment lists below are a **handwritten oracle** derived from
//! `fixtures/reader/mixed-wordml.xml` (never generated by the code under test).
//! The fixture is pinned by sha256. The projection must preserve decoded
//! content, document order and fragment ownership, and the independent verifier
//! must accept the untampered projection.
//!
//! Non-claims: this battery is `[bounded]` to the one pinned mixed fixture
//! (`reader_wordml_profile/v1`); diverse fixtures and the gate live in S04. Raw
//! decoded legal text is never logged.

use std::collections::HashSet;

use ln_decode::reader_contract::{
    check_fragment_span, ReaderSegmentKind, ReaderSemantic, ReaderViewKind,
};
use ln_decode::reader_projection::{
    build_projection, canonical_projection_bytes, ProjectedView, ReaderProjection, SegmentOrigin,
};
use ln_decode::reader_verifier::verify_projection;
use ln_decode::source_package::{capture, Limits, Record};

const XML: &str = include_str!("fixtures/reader/mixed-wordml.xml");
const FIXTURE_SHA256: &str = "d2fc1cd17f0697f575e94f09d83da5027d73afd37c700772eafa4c4a4fbc76db";

fn fixture() -> (Vec<Record>, ReaderProjection) {
    let package = capture(XML.as_bytes(), &Limits::default()).expect("fixture must capture");
    assert_eq!(
        package.manifest().source.sha256,
        FIXTURE_SHA256,
        "fixture content changed; re-pin FIXTURE_SHA256 and the handwritten oracle"
    );
    let records = package.records().to_vec();
    let projection = build_projection(&records).expect("projection must build");
    (records, projection)
}

fn text_record<'a>(
    records: &'a [Record],
    fragment: &str,
) -> &'a ln_decode::source_package::TextRecord {
    records
        .iter()
        .find_map(|record| match record {
            Record::Text(text) if text.id == fragment => Some(text),
            _ => None,
        })
        .unwrap_or_else(|| panic!("fragment {fragment} must name a substrate text record"))
}

fn view<'a>(
    projection: &'a ReaderProjection,
    kind: ReaderViewKind,
    element_ref: &str,
) -> &'a ProjectedView {
    projection
        .views
        .iter()
        .find(|view| view.kind == kind && view.element_ref.as_str() == element_ref)
        .unwrap_or_else(|| panic!("view {kind:?} {element_ref} missing"))
}

fn strings(values: &[&str]) -> Vec<String> {
    values.iter().map(|value| value.to_string()).collect()
}

/// `tN` for a source segment, `derived:<kind>` for a rendered control.
fn segment_tokens(
    projection: &ReaderProjection,
    kind: ReaderViewKind,
    element_ref: &str,
) -> Vec<String> {
    view(projection, kind, element_ref)
        .segment_refs
        .iter()
        .map(|id| {
            let segment = projection
                .segments
                .iter()
                .find(|segment| &segment.id == id)
                .expect("segment ref must resolve");
            match segment.origin {
                SegmentOrigin::SourceFragment => segment
                    .fragment_ref
                    .as_ref()
                    .expect("source segment carries a fragment")
                    .as_str()
                    .to_string(),
                SegmentOrigin::Derived(kind) => format!("derived:{}", kind.as_str()),
            }
        })
        .collect()
}

fn reference_tokens(
    projection: &ReaderProjection,
    kind: ReaderViewKind,
    element_ref: &str,
) -> Vec<String> {
    view(projection, kind, element_ref)
        .reference_refs
        .iter()
        .map(|id| {
            projection
                .references
                .iter()
                .find(|reference| &reference.id == id)
                .expect("reference ref must resolve")
                .reference_type
                .as_str()
                .to_string()
        })
        .collect()
}

#[test]
fn pinned_fixture_verifies_ok() {
    let (records, projection) = fixture();
    assert_eq!(
        records
            .iter()
            .filter(|record| matches!(record, Record::Text(_)))
            .count(),
        15,
        "handwritten tN count"
    );
    assert_eq!(projection.views.len(), 17, "handwritten view count");
    assert_eq!(projection.segments.len(), 18, "15 source + 3 derived");
    assert_eq!(
        projection.references.len(),
        6,
        "handwritten reference count"
    );
    if let Err(findings) = verify_projection(&projection, &records) {
        panic!("untampered fixture projection must verify: {findings:?}");
    }
}

#[test]
fn view_forest_covers_every_view_kind() {
    let (_records, projection) = fixture();
    let kinds: HashSet<ReaderViewKind> = projection.views.iter().map(|view| view.kind).collect();
    for kind in [
        ReaderViewKind::Paragraph,
        ReaderViewKind::Residual,
        ReaderViewKind::Table,
        ReaderViewKind::Row,
        ReaderViewKind::Cell,
        ReaderViewKind::Note,
    ] {
        assert!(kinds.contains(&kind), "projection must carry {kind:?}");
    }
}

#[test]
fn ordered_segment_lists_match_handwritten_oracle() {
    let (_records, projection) = fixture();
    // Hand-derived from the fixture XML; `derived:<kind>` marks a rendered
    // control and the order is the document-event order within each view.
    let oracle: &[(ReaderViewKind, &str, &[&str])] = &[
        (ReaderViewKind::Paragraph, "e2", &["t0"]),
        (
            ReaderViewKind::Paragraph,
            "e5",
            &["t1", "derived:tab", "t2"],
        ),
        (ReaderViewKind::Paragraph, "e13", &["t3"]),
        (ReaderViewKind::Residual, "e13", &["t4"]),
        (ReaderViewKind::Residual, "e16", &["t5"]),
        (
            ReaderViewKind::Paragraph,
            "e19",
            &["derived:line_break", "derived:page_break", "t6"],
        ),
        (ReaderViewKind::Paragraph, "e24", &["t7", "t8"]),
        (ReaderViewKind::Paragraph, "e29", &["t9", "t10"]),
        (ReaderViewKind::Paragraph, "e38", &["t13"]),
        (ReaderViewKind::Paragraph, "e43", &["t14"]),
        (ReaderViewKind::Residual, "e0", &["t11", "t12"]),
        (ReaderViewKind::Residual, "e46", &[]),
    ];
    for (kind, element_ref, expected) in oracle {
        assert_eq!(
            segment_tokens(&projection, *kind, element_ref),
            strings(expected),
            "segments for {kind:?} {element_ref}"
        );
    }

    let references: &[(ReaderViewKind, &str, &[&str])] = &[
        (ReaderViewKind::Paragraph, "e5", &["field"]),
        (ReaderViewKind::Paragraph, "e24", &["field"]),
        (
            ReaderViewKind::Residual,
            "e0",
            &[
                "unknown_wordml_element",
                "foreign_element",
                "note_reference",
            ],
        ),
        (ReaderViewKind::Residual, "e46", &["note_reference"]),
    ];
    for (kind, element_ref, expected) in references {
        assert_eq!(
            reference_tokens(&projection, *kind, element_ref),
            strings(expected),
            "references for {kind:?} {element_ref}"
        );
    }
}

#[test]
fn derived_controls_render_without_source_span() {
    let (_records, projection) = fixture();
    let derived: Vec<_> = projection
        .segments
        .iter()
        .filter(|segment| segment.segment_kind == ReaderSegmentKind::Derived)
        .collect();
    assert_eq!(
        derived.len(),
        3,
        "fixture carries three documented controls"
    );
    for segment in &derived {
        let kind = segment.origin.derived_kind().expect("derived origin");
        assert!(segment.fragment_ref.is_none(), "{}", segment.id);
        assert!(segment.slot.is_none(), "{}", segment.id);
        assert!(segment.span.is_none(), "{}", segment.id);
        assert_eq!(segment.semantic, ReaderSemantic::DerivedSeparator);
        assert!(segment.contextual, "{}", segment.id);
        assert_eq!(
            segment.text.as_deref(),
            Some(kind.literal()),
            "{}",
            segment.id
        );
        assert_eq!(
            segment.chars,
            kind.literal().chars().count(),
            "{}",
            segment.id
        );
    }
}

#[test]
fn references_are_typed_unresolved_and_not_primary_views() {
    let (_records, projection) = fixture();
    let types: HashSet<&str> = projection
        .references
        .iter()
        .map(|reference| reference.reference_type.as_str())
        .collect();
    assert_eq!(
        types,
        HashSet::from([
            "field",
            "note_reference",
            "unknown_wordml_element",
            "foreign_element",
        ])
    );
    for reference in &projection.references {
        assert!(!reference.resolved, "{} must stay unresolved", reference.id);
        // A reference element is never promoted to a paragraph view.
        assert!(
            !projection.views.iter().any(|view| {
                view.element_ref == reference.element_ref && view.kind == ReaderViewKind::Paragraph
            }),
            "reference element {} must not be promoted to a paragraph view",
            reference.element_ref
        );
        // Unknown/foreign subtrees are not promoted to any primary view; fields
        // and note references may legitimately anchor a residual ownership view.
        if matches!(
            reference.reference_type.as_str(),
            "unknown_wordml_element" | "foreign_element"
        ) {
            assert!(
                !projection.views.iter().any(|view| {
                    view.element_ref == reference.element_ref
                        && (view.kind == ReaderViewKind::Paragraph
                            || view.kind == ReaderViewKind::Residual)
                }),
                "unknown/foreign element {} must not be promoted to a primary view",
                reference.element_ref
            );
        }
    }
}

#[test]
fn coverage_is_total_duplicate_free_and_dangling_free() {
    let (records, projection) = fixture();
    let mut seen: HashSet<String> = HashSet::new();
    let mut fragments: Vec<String> = Vec::new();
    for segment in &projection.segments {
        let Some(fragment) = &segment.fragment_ref else {
            continue;
        };
        // Dangling-free: every fragment names a substrate text record.
        let _ = text_record(&records, fragment.as_str());
        assert!(
            seen.insert(fragment.as_str().to_string()),
            "fragment {} referenced twice",
            fragment
        );
        fragments.push(fragment.as_str().to_string());
    }
    fragments.sort_unstable();
    let mut expected: Vec<String> = (0..15).map(|index| format!("t{index}")).collect();
    expected.sort_unstable();
    assert_eq!(
        fragments, expected,
        "coverage must be total over the tN set"
    );
}

#[test]
fn every_source_segment_carries_a_valid_whole_fragment_span() {
    let (records, projection) = fixture();
    for segment in &projection.segments {
        let Some(fragment) = &segment.fragment_ref else {
            assert!(
                segment.span.is_none(),
                "derived {} must not carry a span",
                segment.id
            );
            continue;
        };
        let text = text_record(&records, fragment.as_str());
        let value = text.value.as_str();
        let span = segment
            .span
            .as_ref()
            .expect("source segment carries a span");
        assert_eq!(span.fragment, *fragment, "{}", segment.id);
        assert_eq!(span.start, 0, "{}", segment.id);
        assert_eq!(span.end, value.len(), "{}", segment.id);
        check_fragment_span(value, span).expect("span must validate");
        assert_eq!(segment.slot, Some(text.slot), "{}", segment.id);
        assert_eq!(segment.chars, value.chars().count(), "{}", segment.id);
        assert_eq!(
            segment.output_end - segment.output_start,
            value.len(),
            "{}",
            segment.id
        );
    }
}

#[test]
fn canonical_bytes_are_deterministic_and_seal_is_stable() {
    let (_records, mut projection) = fixture();
    let first = canonical_projection_bytes(&projection);
    let second = canonical_projection_bytes(&projection);
    assert_eq!(first, second, "canonical bytes must be deterministic");
    assert!(first.ends_with('\n'), "canonical stream is LF-terminated");
    assert!(!first.contains('\r'), "canonical stream must not carry CR");

    projection.reseal();
    let hash = projection.content_hash().expect("sealed").to_string();
    assert_eq!(hash.len(), 64);
    assert!(hash.chars().all(|ch| ch.is_ascii_hexdigit()));
    assert_eq!(hash, hash.to_ascii_lowercase());

    // The seal is recomputable and idempotent; it never feeds its own input.
    projection.content_hash = None;
    projection.reseal();
    assert_eq!(projection.content_hash(), Some(hash.as_str()));
}
